///         do! Promise.sleep 10
///         return! Promise.reject (exn "I Failed First")
///     }
/// let rejection2() =
///     promise {
///         do! Promise.sleep 50
///         return! Promise.reject (exn "I Failed Last")
///     }
/// 
/// Promise.race [rejection2(); rejection(); success()]
/// |> Promise.map(fun result ->
