namespace Sutil

open System
open Sutil.Core
open Sutil.CoreElements
open Sutil.Transition
open Sutil.DomHelpers
open Fable.Core.JsInterop
open Sutil.Interop
open Feliz

/// <summary>
/// Helpers for listening and reacting to media changes
/// </summary>
type Media =
    /// <summary>
    /// </summary>
    static member listenMedia (query:string, handler : bool -> unit) : unit -> unit =
        let mql = Window.matchMedia( query )
        handler (mql.matches)
        listen "change" mql (fun e -> e?matches |> handler)

    /// <summary>
    /// </summary>
    static member bindMediaQuery (query:string, view : bool -> SutilElement) =
        let s = Store.make false
        let u = Media.listenMedia(query,fun m -> s <~ m)
        fragment [
            disposeOnUnmount [ Helpers.disposable u; s ]
            Bind.el(s,view)
        ]

    /// <summary>
    /// </summary>
    static member showIfMedia (query:string, f:bool->bool, trans, view : SutilElement) =
        let s = Store.make false
        let u = Media.listenMedia(query, fun m -> s <~ m)
        fragment [
            disposeOnUnmount [ Helpers.disposable u; s ]
            transition trans (s .> f) view
        ]

    /// <summary>
    /// </summary>
    static member showIfMedia (query:string, trans, view : SutilElement) =
        Media.showIfMedia(query,id,trans,view)

    /// <summary>
    /// </summary>
    static member media<'T> (query:string, map:bool -> 'T, app : IObservable<'T> -> SutilElement) =
        let s = Store.make false
        let u = Media.listenMedia(query,fun m -> s <~ m)
        fragment [
            disposeOnUnmount [ Helpers.disposable u; s ]
            s .> map |> app
        ]

/// <summary>
/// Helpers for basic CSS media queries
/// </summary>
type CssMedia =
    /// <summary>
    /// Create a <c>@media</c> CSS rule for a custom condition and stylesheet
    /// </summary>
    static member custom (condition : string, rules) =
        Styling.makeMediaRule condition rules
    /// <summary>
    /// Create a <c>@media (min-width: &lt;nnn>)</c> CSS rule
    /// </summary>
    static member minWidth (minWidth : Styles.ICssUnit, rules : StyleSheetDefinition list) =
        Styling.makeMediaRule (sprintf "(min-width: %s)" (string minWidth)) rules
    /// <summary>
    /// Create a <c>@media (max-width: &lt;nnn>)</c> CSS rule
    /// </summary>
    static member maxWidth (maxWidth : Styles.ICssUnit, rules : StyleSheetDefinition list) =
        Styling.makeMediaRule (sprintf "(max-width: %s)" (string maxWidth)) rules

src/App/fable_modules/Sutil.2.0.16/Navig:
namespace Sutil

open Sutil
open Browser.Types
open Core
open CoreElements
open System
open Interop

/// <summary>
/// Window location events
/// </summary>
module Navigable =
    /// <summary>
    /// Parser that can convert <c>Location</c> to a <c>'T</c>. For example, convert the url <c>https//sutil.dev/#documentation</c> into
    /// the DU value <c>Pages.Documenation</c>
    /// </summary>
    type Parser<'T> = Location -> 'T

open Navigable

/// <summary>
/// Window location events
/// </summary>
type Navigable =

    /// <summary>
    /// Call <c>dispatch</c> each time the window's location changes. The location is parsed into a <c>'T</c> with the given <c>parser</c>/
    /// </summary>
    static member listenLocation (onChangeLocation: Location -> unit) =
        let mutable onChangeRef : obj -> obj =
            fun _ ->
                failwith "`onChangeRef` has not been initialized.\nPlease make sure you used Elmish.Navigation.Program.Internal.subscribe"

        let subscribe () =
            let mutable lastLocation = None
            let onChange _ =
                match lastLocation with
                | Some href when href = Window.location.href -> ()
                | _ ->
                    lastLocation <- Some Window.location.href
                    Window.location |> onChangeLocation
                |> box

            onChangeRef <- onChange

            Window.addEventListener("popstate", unbox onChangeRef)
            Window.addEventListener("hashchange", unbox onChangeRef)

            onChange() |> ignore // Initialize with starting href

        let unsubscribe () =
            Window.removeEventListener("popstate", unbox onChangeRef)
            Window.removeEventListener("hashchange", unbox onChangeRef)

        subscribe()

        unsubscribe

    /// <summary>
    /// Call <c>dispatch</c> each time the window's location changes. The location is parsed into a <c>'T</c> with the given <c>parser</c>/
    /// </summary>
    static member listenLocation<'T> (parser:Parser<'T>, dispatch: 'T -> unit) =
        Navigable.listenLocation (dispatch<<parser)

    /// <summary>
    /// Bind the window location to a view
    /// </summary>
    static member bindLocation<'T> ( view : Location -> SutilElement ) =
        let store = Store.make (Window.location)
        fragment [
            disposeOnUnmount [
                store
                Navigable.listenLocation(id,Store.set store) |> Helpers.disposable
            ]
            Bind.el( store, view )
        ]

